import json
from datetime import datetime
from ortools.sat.python import cp_model

# Input data
max_rooms = 5
start_data = ["2024-05-01", "2024-05-02", "2024-05-03", "2024-05-04"]
end_data   = ["2024-05-05", "2024-05-06", "2024-05-07", "2024-05-08"]
preassigned_room_data = [3, -1, -1, -1]

# Convert date strings to integer ordinals for easy comparison
def to_ordinal(date_str):
    return datetime.strptime(date_str, "%Y-%m-%d").date().toordinal()

n = len(start_data)
starts = [to_ordinal(d) for d in start_data]
ends   = [to_ordinal(d) for d in end_data]

model = cp_model.CpModel()

# Decision variables: room assignment for each request (1..max_rooms)
room = [
    model.NewIntVar(1, max_rooms, f"room_{i}")
    for i in range(n)
]

# Apply pre-assignments
for i, pre in enumerate(preassigned_room_data):
    if pre != -1:
        model.Add(room[i] == pre)

# No-overlap constraint: if requests overlap in time, they must be in different rooms
for i in range(n):
    for j in range(i + 1, n):
        # They overlap if start_i < end_j and start_j < end_i
        if not (ends[i] <= starts[j] or ends[j] <= starts[i]):
            model.Add(room[i] != room[j])

# Solve
solver = cp_model.CpSolver()
status = solver.Solve(model)

# Print results as JSON
if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
    solution = {
        "room_assignments": [solver.Value(room[i]) for i in range(n)]
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
