import json
from ortools.sat.python import cp_model

def solve_sudoku(input_grid):
    model = cp_model.CpModel()

    # Create 9x9 matrix of variables with domain 1..9
    grid = []
    for i in range(9):
        row = []
        for j in range(9):
            cell = model.NewIntVar(1, 9, f"cell_{i}_{j}")
            row.append(cell)
        grid.append(row)

    # Apply the given clues
    for i in range(9):
        for j in range(9):
            if input_grid[i][j] != 0:
                model.Add(grid[i][j] == input_grid[i][j])

    # Row constraints
    for i in range(9):
        model.AddAllDifferent(grid[i])

    # Column constraints
    for j in range(9):
        col = [grid[i][j] for i in range(9)]
        model.AddAllDifferent(col)

    # 3x3 block constraints
    for bi in range(3):
        for bj in range(3):
            block = []
            for di in range(3):
                for dj in range(3):
                    block.append(grid[3*bi + di][3*bj + dj])
            model.AddAllDifferent(block)

    # Solve model
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    # Print solution as JSON
    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        solved = [
            [solver.Value(grid[i][j]) for j in range(9)]
            for i in range(9)
        ]
        result = {'grid': solved}
        print(json.dumps(result, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
    input_grid = [
        [0, 0, 0,  2, 0, 5,  0, 0, 0],
        [0, 9, 0,  0, 0, 0,  7, 3, 0],
