import json
from ortools.sat.python import cp_model

def main():
    # Input data
    n_slots = 9       # slots per template
    n_templates = 2   # number of templates
    n_var = 7         # number of variations
    demand = [250, 255, 260, 500, 500, 800, 1100]

    max_demand = max(demand)

    model = cp_model.CpModel()

    # Decision variables
    # x[t] = number of sheets to print of template t
    x = [model.NewIntVar(0, max_demand, f'x[{t}]') for t in range(n_templates)]

    # assign[(t,s,v)] = 1 if on template t, slot s is assigned to variation v
    assign = {}
    for t in range(n_templates):
        for s in range(n_slots):
            for v in range(n_var):
                assign[(t, s, v)] = model.NewBoolVar(f'assign[{t},{s},{v}]')

    # Each slot on each template must be assigned exactly one variation
    for t in range(n_templates):
        for s in range(n_slots):
            model.Add(
                sum(assign[(t, s, v)] for v in range(n_var)) == 1
            )

    # To linearize x[t] * assign[(t,s,v)], introduce an intermediate var z[(t,s,v)]
    # z[(t,s,v)] = x[t] if assign[(t,s,v)] == 1, else 0
    z = {}
    for t in range(n_templates):
        for s in range(n_slots):
            for v in range(n_var):
                z[(t, s, v)] = model.NewIntVar(0, max_demand, f'z[{t},{s},{v}]')
                model.AddMultiplicationEquality(
                    z[(t, s, v)], [x[t], assign[(t, s, v)]]
                )

    # Demand satisfaction: for each variation v, total produced >= demand[v]
    for v in range(n_var):
        model.Add(
            sum(z[(t, s, v)]
                for t in range(n_templates)
                for s in range(n_slots)
               ) >= demand[v]
        )

    # Objective: minimize total number of printed sheets
    model.Minimize(sum(x))

    # Solve
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        # Extract production per template
        production = [solver.Value(x[t]) for t in range(n_templates)]
        # Extract layout: for each template t, list of variation indices per slot
        layout = []
        for t in range(n_templates):
            tmpl = []
            for s in range(n_slots):
                for v in range(n_var):
                    if solver.Value(assign[(t, s, v)]) == 1:
                        tmpl.append(v)
                        break
            layout.append(tmpl)

        solution = {
            'production': production,
            'layout': layout
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == '__main__':
    main()
```

