Here is a pure-Python/OR-Tools CP-SAT model for the Social Golfers Problem with 9 golfers (3 groups of 3) over 4 weeks, forbidding any pair of golfers to meet more than once.  It prints out, week by week, which golfers (numbered 1–9) form each group.

```python
import json
from ortools.sat.python import cp_model

def main():
    # Problem data
    n_weeks = 4
    n_groups = 3
    group_size = 3
    n_golfers = n_groups * group_size  # 9

    model = cp_model.CpModel()

    # x[w][g][i][p] == 1 iff in week w, group g, position i, we have golfer p.
    x = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            for i in range(group_size):
                for p in range(n_golfers):
                    x[(w, g, i, p)] = model.NewBoolVar(f"x_w{w}g{g}i{i}p{p}")

    # 1) Every slot (w,g,i) is occupied by exactly one golfer.
    for w in range(n_weeks):
        for g in range(n_groups):
            for i in range(group_size):
                model.Add(
                    sum(x[(w, g, i, p)] for p in range(n_golfers)) == 1
                )

    # 2) Every golfer p plays exactly once per week w.
    for w in range(n_weeks):
        for p in range(n_golfers):
            model.Add(
                sum(x[(w, g, i, p)]
                    for g in range(n_groups)
                    for i in range(group_size)) == 1
            )

    # 3) Introduce y[w,g,p,q] == 1 if golfers p<q meet in week w in group g.
    #    Then enforce that any pair meets at most once over all weeks/groups.
    y = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            for p in range(n_golfers):
                for q in range(p + 1, n_golfers):
                    y[(w, g, p, q)] = model.NewBoolVar(f"y_w{w}g{g}p{p}q{q}")
                    sum_p = sum(x[(w, g, i, p)] for i in range(group_size))
                    sum_q = sum(x[(w, g, i, q)] for i in range(group_size))
                    # If both p and q are in that group, y=1
                    model.Add(sum_p + sum_q <= y[(w, g, p, q)] * 2 + 1)
                    model.Add(sum_p >= y[(w, g, p, q)])
                    model.Add(sum_q >= y[(w, g, p, q)])

    # 4) Any pair (p,q) meets at most once overall
    for p in range(n_golfers):
        for q in range(p + 1, n_golfers):
            model.Add(
                sum(
                    y[(w, g, p, q)]
                    for w in range(n_weeks)
                    for g in range(n_groups)
                )
                <= 1
            )

    # Solve
    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    # Print solution as JSON
    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        # Build assignment structure: weeks × groups × golfers
        assign = []
        for w in range(n_weeks):
            week_groups = []
            for g in range(n_groups):
                group = []
                for i in range(group_size):
                    for p in range(n_golfers):
                        if solver.Value(x[(w, g, i, p)]) == 1:
                            # Use 1-based golfer numbering
                            group.append(p + 1)
                            break
                week_groups.append(group)
            assign.append(week_groups)

        solution = {
            "assign": assign
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
    main()
```

Explanation of key points:
1. We index golfers `p` from 0 to 8 (printed as 1–9).
2. `x[(w,g,i,p)]` is a Boolean: golfer `p` in week `w`, group `g`, position `i`.
3. We force each slot to be filled by exactly one golfer, and each golfer to appear exactly once per week.
4. For each potential pair `(p,q)` with `p<q`, and for each week/group, we introduce a helper Boolean `y[(w,g,p,q)]` that is 1 precisely if `p` and `q` end up together in that group.  Linear inequalities enforce `y` = 1 ⇒ both are assigned there, and if both are assigned then `y` = 1.
5. Finally we require ∑_weeks,groups y[(w,g,p,q)] ≤ 1 so no pair meets more than once across all weeks.
6. The solution is printed in JSON as
   {
     "assign": [
       [ [g1_week0],[g2_week0],[g3_week0] ],
       [ [g1_week1],... ],
       …
     ]
   }

