    # 1. Each team plays exactly once (home, away or bye) each round
    for i in range(n_teams):
        for r in range(n_days):
            home_games = [x[(i, j, r)] for j in range(n_teams) if j != i]
            away_games = [x[(j, i, r)] for j in range(n_teams) if j != i]
            model.Add(sum(home_games) + sum(away_games) + bye[(i, r)] == 1)

    # 2. Double round robin: each ordered pair meets exactly once
    for i in range(n_teams):
        for j in range(i+1, n_teams):
            # i home vs j once
            model.Add(sum(x[(i, j, r)] for r in range(n_days)) == 1)
            # j home vs i once
            model.Add(sum(x[(j, i, r)] for r in range(n_days)) == 1)

    # 3. Mirroring scheme
    mirror_pairs = [(0,7), (1,8), (2,11), (3,12), (4,13), (5,14),
                    (6,15), (9,16), (10,17)]
    for (r1, r2) in mirror_pairs:
        for i in range(n_teams):
            for j in range(i+1, n_teams):
                model.Add(x[(i, j, r1)] + x[(j, i, r1)] ==
                          x[(i, j, r2)] + x[(j, i, r2)])

    # 4. No two final aways: rounds 17,18 => indices 16,17
    for i in range(n_teams):
        away17 = sum(x[(j, i, 16)] for j in range(n_teams) if j != i)
        away18 = sum(x[(j, i, 17)] for j in range(n_teams) if j != i)
