                     for rr in range(r, r+3))
            model.Add(a3 <= 2)
    # b) No more than 2 homes in a row
    for i in range(n_teams):
        for r in range(n_days - 2):
            h3 = sum(x[(i, j, rr)] for j in range(n_teams) if j != i
                     for rr in range(r, r+3))
            model.Add(h3 <= 2)
    # c) No more than 3 away+bye in a row
    for i in range(n_teams):
        for r in range(n_days - 3):
            ab4 = (sum(x[(j, i, rr)] for j in range(n_teams) if j != i
                       for rr in range(r, r+4))
                   + sum(bye[(i, rr)] for rr in range(r, r+4)))
            model.Add(ab4 <= 3)
    # d) No more than 4 home+bye in a row
    for i in range(n_teams):
        for r in range(n_days - 4):
            hb5 = (sum(x[(i, j, rr)] for j in range(n_teams) if j != i
                       for rr in range(r, r+5))
                   + sum(bye[(i, rr)] for rr in range(r, r+5)))
            model.Add(hb5 <= 4)

    # 6. Weekend pattern: even dates = 2,4,...,18 => indices 1,3,...,17
    weekends = [r for r in range(n_days) if (r+1) % 2 == 0]
    for i in range(n_teams):
        home_w = sum(x[(i, j, r)] for j in range(n_teams) if j != i
                     for r in weekends)
        away_w = sum(x[(j, i, r)] for j in range(n_teams) if j != i
                     for r in weekends)
        bye_w = sum(bye[(i, r)] for r in weekends)
        model.Add(home_w == 4)
        model.Add(away_w == 4)
        model.Add(bye_w == 1)

    # 7. First five weekends: rounds 2,4,6,8,10 => idx 1,3,5,7,9
    first5 = [1,3,5,7,9]
    for i in range(n_teams):
        occ = sum(x[(i, j, r)] + bye[(i, r)]
                  for j in range(n_teams) if j != i
                  for r in first5)
        model.Add(occ >= 2)

    # 8. Rival matches on last date (18 => idx 17)
    rivals = {
        'Duke': 'UNC',
        'UNC': 'Duke',
        'Clem': 'GT',
        'GT': 'Clem',
        'NCSt': 'Wake',
        'Wake': 'NCSt',
        'UMD': 'UVA',
        'UVA': 'UMD'
    }
    fsui = team_idx['FSU']
    r18 = 17
    for t, rt in rivals.items():
        i = team_idx[t]
        j = team_idx[rt]
        # only if not bye and not vs FSU
        b_not_bye = model.NewBoolVar(f"nb_{t}_r18")
        model.Add(b_not_bye + bye[(i, r18)] == 1)
        b_play_fsu = model.NewBoolVar(f"pf_{t}_r18")
        model.AddMaxEquality(b_play_fsu, [x[(i, fsui, r18)], x[(fsui, i, r18)]])
        b_not_fsu = model.NewBoolVar(f"nf_{t}_r18")
        model.Add(b_not_fsu + b_play_fsu == 1)
        b_cond = model.NewBoolVar(f"cond_{t}_r18")
        model.AddBoolAnd([b_not_bye, b_not_fsu]).OnlyEnforceIf(b_cond)
        b_play_rival = model.NewBoolVar(f"pr_{t}_{rt}_r18")
        model.AddMaxEquality(b_play_rival,
                             [x[(i, j, r18)], x[(j, i, r18)]])
        # if cond then must play rival
        model.Add(b_play_rival == 1).OnlyEnforceIf(b_cond)

    # 9. Constrained matches in rounds 11-18 => idx 10..17
    req_pairs = [('Wake','UNC'), ('Wake','Duke'),
                 ('GT','UNC'), ('GT','Duke')]
    for ta, tb in req_pairs:
        ia, ib = team_idx[ta], team_idx[tb]
        model.Add(
            sum(x[(ia, ib, r)] + x[(ib, ia, r)]
                for r in range(10, 18)) >= 1
        )

