    unci = team_idx['UNC']
    dukei = team_idx['Duke']
    wakei = team_idx['Wake']
    # a) no two consecutive away vs UNC/Duke
    for i in range(n_teams):
        if i in (unci, dukei):
            continue
        for r in range(n_days - 1):
            c = (x[(unci, i, r)] + x[(dukei, i, r)] +
                 x[(unci, i, r+1)] + x[(dukei, i, r+1)])
            model.Add(c <= 1)
    # b) no three consecutive vs UNC, Duke, Wake (any home/away)
    opps = [unci, dukei, wakei]
    for i in range(n_teams):
        for r in range(n_days - 2):
            total = []
            for p in opps:
                total += [x[(i, p, r+k)] + x[(p, i, r+k)]
                          for k in range(3)]
            model.Add(sum(total) <= 2)

    # 11. Other specific constraints
    # UNC-Duke in r11 and r18
    model.Add(x[(unci, dukei, 10)] + x[(dukei, unci, 10)] == 1)
    model.Add(x[(unci, dukei, 17)] + x[(dukei, unci, 17)] == 1)
    # UNC-Clem in r2
    clemi = team_idx['Clem']
    model.Add(x[(unci, clemi, 1)] + x[(clemi, unci, 1)] == 1)
    # Duke bye r16 (idx15)
    model.Add(bye[(dukei, 15)] == 1)
    # Wake not home r17 (idx16)
    for j in range(n_teams):
        if j != wakei:
            model.Add(x[(wakei, j, 16)] == 0)
    # Wake bye r1 (idx0)
    model.Add(bye[(wakei, 0)] == 1)
    # Clem, Duke, UMD, Wake not away r18
    for t in ['Clem','Duke','UMD','Wake']:
        ti = team_idx[t]
        for j in range(n_teams):
            if j != ti:
                model.Add(x[(j, ti, 17)] == 0)
    # Clem, FSU, GT, Wake not away r1
    for t in ['Clem','FSU','GT','Wake']:
        ti = team_idx[t]
        for j in range(n_teams):
            if j != ti:
                model.Add(x[(j, ti, 0)] == 0)
    # No bye for FSU, NCSt in r18
    model.Add(bye[(team_idx['FSU'], 17)] == 0)
    model.Add(bye[(team_idx['NCSt'], 17)] == 0)
    # UNC no bye r1
    model.Add(bye[(team_idx['UNC'], 0)] == 0)

    # Solve
    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    status = solver.Solve(model)

    if status in (cp_model.FEASIBLE, cp_model.OPTIMAL):
        # Build config and where
        config = []
        for r in range(n_days):
            day_matches = []
            for i in range(n_teams):
                for j in range(i+1, n_teams):
                    if solver.Value(x[(i, j, r)]) == 1:
                        day_matches.append((teams[i], teams[j]))
                    elif solver.Value(x[(j, i, r)]) == 1:
                        day_matches.append((teams[j], teams[i]))
            config.append(day_matches)

        where = {t: [] for t in teams}
        for i, t in enumerate(teams):
            for r in range(n_days):
                if solver.Value(bye[(i, r)]) == 1:
                    where[t].append('B')
                else:
                    # check home/away
                    home = any(solver.Value(x[(i, j, r)]) for j in range(n_teams) if j != i)
                    away = any(solver.Value(x[(j, i, r)]) for j in range(n_teams) if j != i)
                    where[t].append('H' if home else 'A')

        solution = {
            'config': config,
            'where': where
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
