def solve_progressive_party(n_boats, n_periods, capacity, crew_size):
    model = cp_model.CpModel()

    # Decision variables
    # is_host[b] = 1 if boat b is a host
    is_host = [model.NewBoolVar(f'is_host[{b}]') for b in range(n_boats)]

    # visits[b][h][t] = 1 if boat b visits host h in period t
    visits = {}
    for b in range(n_boats):
        for h in range(n_boats):
            for t in range(n_periods):
                visits[b, h, t] = model.NewBoolVar(f'visits[{b},{h},{t}]')

    # HOST / GUEST STRUCTURE
    for b in range(n_boats):
        for t in range(n_periods):
            # If b is a host, it makes no visit; otherwise exactly one visit each period
            model.Add(
                sum(visits[b, h, t] for h in range(n_boats)) ==
                1 - is_host[b]
            )
        # A host does not visit itself, and guest also should not visit itself
        for t in range(n_periods):
            model.Add(visits[b, b, t] == 0)

    # A boat can only visit if the target is a host
    for b in range(n_boats):
        for h in range(n_boats):
            for t in range(n_periods):
                model.Add(visits[b, h, t] <= is_host[h])

    # CAPACITY CONSTRAINTS
    for h in range(n_boats):
        for t in range(n_periods):
            # sum of crews visiting h at t plus h's own crew <= capacity[h]
            model.Add(
                sum(crew_size[b] * visits[b, h, t]
                    for b in range(n_boats)) +
                crew_size[h] <= capacity[h]
            )

    # A guest cannot revisit the same host
    for b in range(n_boats):
        for h in range(n_boats):
            model.Add(sum(visits[b, h, t] for t in range(n_periods)) <= 1)

    # GUEST PAIR MEETING CONSTRAINT: No two guests meet more than once
    # meet[b1,b2,h,t] == 1 if b1 and b2 both visit h at t
    meet = {}
    for b1 in range(n_boats):
        for b2 in range(b1 + 1, n_boats):
            for h in range(n_boats):
                for t in range(n_periods):
                    m = model.NewBoolVar(f'meet[{b1},{b2},{h},{t}]')
                    meet[b1, b2, h, t] = m
                    model.AddBoolAnd([visits[b1, h, t],
                                      visits[b2, h, t]]).OnlyEnforceIf(m)
                    # If either visit var is 0, meet must be 0
                    model.AddImplication(m, visits[b1, h, t])
                    model.AddImplication(m, visits[b2, h, t])
            # Sum of all meets for this pair <= 1
            model.Add(
                sum(meet[b1, b2, h, t]
                    for h in range(n_boats)
                    for t in range(n_periods)) <= 1
            )

    # OBJECTIVE: minimize number of hosts
    model.Minimize(sum(is_host))

    # Solve
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    # Print solution as JSON
    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        sol = {
            'is_host': [int(solver.Value(is_host[b])) for b in range(n_boats)],
            'visits': [
                [
                    [int(solver.Value(visits[b, h, t]))
                     for t in range(n_periods)]
                    for h in range(n_boats)]
                for b in range(n_boats)
            ]
        }
        print(json.dumps(sol, indent=4))
    else:
        print("No solution found.")

if __name__ == '__main__':
    # Input data
    n_boats = 5
    n_periods = 4
    capacity = [6, 8, 12, 12, 12]
    crew_size = [2, 2, 2, 2, 4]

