def solve_schur(n=13, c=3):
    model = cp_model.CpModel()

    # Decision variables: M[i][j] = 1 if ball i+1 is in box j+1
    M = []
    for i in range(n):
        row = []
        for j in range(c):
            row.append(model.NewBoolVar(f"M_{i+1}_{j+1}"))
        M.append(row)

    # Each ball must go into exactly one box
    for i in range(n):
        model.Add(sum(M[i][j] for j in range(c)) == 1)

    # Schur constraints: for any x + y = z, balls x,y,z cannot all be in the same box
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            z = x + y
            if z <= n:
                for j in range(c):
                    model.Add(M[x-1][j] + M[y-1][j] + M[z-1][j] <= 2)

    # Solve
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    # Print result as JSON
    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        balls = []
        for i in range(n):
            # find which box j has M[i][j] = 1
            for j in range(c):
                if solver.Value(M[i][j]) == 1:
                    balls.append(j+1)
                    break
        solution = {
            'balls': balls
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
