    #  week[m] in [0..weeks-1], period[m] in [0..periods-1], home1[m] in {0,1}
    week = [model.NewIntVar(0, weeks - 1, f"week[{m}]") for m in range(num_matches)]
    period = [model.NewIntVar(0, periods - 1, f"period[{m}]") for m in range(num_matches)]
    home1 = [model.NewBoolVar(f"home1[{m}]") for m in range(num_matches)]
    # A linearized position = week * periods + period to ensure exactly one match per slot
    slot = [model.NewIntVar(0, weeks * periods - 1, f"slot[{m}]")
            for m in range(num_matches)]
    for m in range(num_matches):
        model.Add(slot[m] == week[m] * periods + period[m])
    model.AddAllDifferent(slot)

    # Indicators is_week[m][w] = 1 if match m is in week w
    is_week = {}
    for m in range(num_matches):
        for w in range(weeks):
            b = model.NewBoolVar(f"is_week[{m},{w}]")
            is_week[(m, w)] = b
            # b => week[m] == w, not(b) => week[m] != w
            model.Add(week[m] == w).OnlyEnforceIf(b)
            model.Add(week[m] != w).OnlyEnforceIf(b.Not())

    # Indicators is_period[m][p] = 1 if match m is in period p
    is_period = {}
    for m in range(num_matches):
        for p in range(periods):
            b = model.NewBoolVar(f"is_period[{m},{p}]")
            is_period[(m, p)] = b
            model.Add(period[m] == p).OnlyEnforceIf(b)
            model.Add(period[m] != p).OnlyEnforceIf(b.Not())

    # Constraint: each team plays exactly once per week
    for team in range(n_teams):
        for w in range(weeks):
            plays = []
            for m, (t1, t2) in enumerate(matches):
                if t1 == team or t2 == team:
                    plays.append(is_week[(m, w)])
            model.Add(sum(plays) == 1)

    # Constraint: each team appears at most twice in the same period over the tournament
    for team in range(n_teams):
        for p in range(periods):
            plays = []
            for m, (t1, t2) in enumerate(matches):
                if t1 == team or t2 == team:
                    plays.append(is_period[(m, p)])
            model.Add(sum(plays) <= 2)

    # Solve
    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30
    status = solver.Solve(model)

    if status not in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        print("No solution found.")
        return

    # Build the first (home) schedule
