        p = solver.Value(period[m])
        if solver.Value(home1[m]) == 1:
            home_team, away_team = t1, t2
        else:
            home_team, away_team = t2, t1
        home_schedule[w][p] = [home_team, away_team]

    # Build the second (away) schedule by swapping home/away in the same pattern
    away_schedule = [
