from ortools.sat import cp_model
import json

def main():
    # Input data
    weights = [4, 3, 1, 3, 2, 5, 2]
    capacity = 5
    num_bins = 5
    num_items = len(weights)

    model = cp_model.CpModel()

    # Decision variables
    # bvar[i][b] = 1 if item i is assigned to bin b.
    bvar = {}
    for i in range(num_items):
        for b in range(num_bins):
            bvar[(i, b)] = model.NewBoolVar(f"b_{i}_{b}")

    # Each item must go to exactly one bin.
    for i in range(num_items):
        model.Add(sum(bvar[(i, b)] for b in range(num_bins)) == 1)

    # Capacity constraint for each bin.
    for b in range(num_bins):
        model.Add(
            sum(weights[i] * bvar[(i, b)] for i in range(num_items))
            <= capacity
        )

    # (Optional) No objective since it's a feasibility problem.
    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        # Extract the bin assignment for each item.
        bins = []
        for i in range(num_items):
            assigned_bin = None
            for b in range(num_bins):
                if solver.Value(bvar[(i, b)]) == 1:
                    assigned_bin = b
                    break
            bins.append(assigned_bin)

        solution = {
            "bins": bins
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
    main()
