import json
from ortools.sat.python import cp_model

def main():
    ratings = [2, 3, 4, 4, 4, 2, 1, 3, 4]
    n = len(ratings)

    model = cp_model.CpModel()

    # Upper bound for candies: in the worst case of a strictly increasing sequence
    # we need at most n candies for the last child.
    max_candies = n

    candies = [
        model.NewIntVar(1, max_candies, f"c_{i}")
        for i in range(n)
    ]

    # Add the jealousy constraints
    for i in range(n - 1):
        if ratings[i] > ratings[i + 1]:
            model.Add(candies[i] > candies[i + 1])
        elif ratings[i] < ratings[i + 1]:
            model.Add(candies[i] < candies[i + 1])
        # if equal, no constraint

    # Minimize total candies
    total_candies = sum(candies)
    model.Minimize(total_candies)

    solver = cp_model.CpSolver()
    status = solver.Solve(model)

    if status == cp_model.OPTIMAL or status == cp_model.FEASIBLE:
        solution = {
            'z': solver.ObjectiveValue()
        }
        print(json.dumps(solution, indent=4))
    else:
        print("No solution found.")

if __name__ == "__main__":
    main()
```

